import{_ as n,a0 as u,w as i,s,ao as l,I as a,x as t,a1 as e,A as p}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const S=JSON.parse('{"title":"为地铁站构建一个智能停车系统 | LCTT x X-CMD","titleTemplate":false,"description":"为地铁站构建一个智能停车系统 | LCTT (202207) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"为地铁站构建一个智能停车系统 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"为地铁站构建一个智能停车系统 | LCTT (202207) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202207/20220614 Build a Smart Parking System for a Metro Station","title":"为地铁站构建一个智能停车系统","tag":"202207","desc":""},"relativePath":"202207/20220614 Build a Smart Parking System for a Metro Station.md","filePath":"[post].md"}'),b={name:"202207/20220614 Build a Smart Parking System for a Metro Station.md"};function d(m,r,g,c,y,f){const o=u("Link");return i(),s("div",null,[r[15]||(r[15]=l('<h1 id="为地铁站构建一个智能停车系统" tabindex="-1">为地铁站构建一个智能停车系统 <a class="header-anchor" href="#为地铁站构建一个智能停车系统" aria-label="Permalink to “为地铁站构建一个智能停车系统”">​</a></h1><blockquote><p>本文将帮助你设计一个基于 Web 的应用程序，使用 Node-RED 为地铁站的汽车提供一个自动智能停车系统。</p></blockquote><p><img src="https://www.opensourceforu.com/wp-content/uploads/2022/04/Smart-car-parking.jpg" alt="Smart car parking"></p><p>Web 应用程序是在 Web 服务器上运行的软件。终端用户通过 Web 浏览器访问 Web 应用程序。Web 应用程序使用客户端—服务器（C/S）架构进行编程，该架构是用户（客户端）通过远程服务器（可能由第三方托管）提供服务。Web API（应用程序编程接口）在整个 Web 上是可用的，用户可以通过 HTTP 协议访问该接口，如图 1 所示。</p><p><img src="https://www.opensourceforu.com/wp-content/uploads/2022/04/Figure-1-Web-Application-Programming-Interface300.jpg" alt="Figure 1: Web API"></p><p>本文将演示如何为地铁设计一个基于 Web 的汽车自动智能停车系统。 它是使用开源的 Node-RED 设计。该系统使用模板节点创建了一个交互式的、时尚的用户登录表单，用 HTML 和 CSS 编码以获取车主的详细信息，从而实现停车系统的自动化。我们可以在图 2 和图 3 看到登录表单和提交表单的流程图。</p><p>使用的节点如下：</p><p><img src="https://www.opensourceforu.com/wp-content/uploads/2022/04/table-function-node-red.jpg" alt="table function"></p><h3 id="地铁智能停车节点流程设计" tabindex="-1">地铁智能停车节点流程设计 <a class="header-anchor" href="#地铁智能停车节点流程设计" aria-label="Permalink to “地铁智能停车节点流程设计”">​</a></h3><p>Node-RED 由 <code>node-red</code> 命令激活。访问网址 <code>http://127.0.0.1:1880/</code> 可以看到 Node-RED 用户界面流程浏览器已经启用，可以认为 Node-RED 设置已完成，可以正常工作了。</p><p>按照下面给出的步骤创建登录表单和提交表单。</p><p><img src="https://www.opensourceforu.com/wp-content/uploads/2022/04/Figure-2-Login-Form-Flow-Diagram300.jpg" alt="Figure 2: Login form flow diagram"></p><p><img src="https://www.opensourceforu.com/wp-content/uploads/2022/04/Figure-3-Submission-Form-Flow-Diagram300.jpg" alt="Figure 3: Submission form flow diagram"></p><h3 id="登录表单" tabindex="-1">登录表单 <a class="header-anchor" href="#登录表单" aria-label="Permalink to “登录表单”">​</a></h3><p>1、在节点画布中，拖放 <ruby>http 输入<rt>http in</rt></ruby> 节点，这会为创建 Web 服务创建一个 HTTP 访问点。</p><p>2、将 <ruby>http 输入<rt>http in</rt></ruby> 节点连接到 <ruby>函数<rt>function</rt></ruby> 节点。函数节点有助于编写 JavaScript 函数处理节点接收到的消息。</p><p><img src="https://www.opensourceforu.com/wp-content/uploads/2022/04/Figure-4-Login-Form-of-Metro-Smart-Car-Parking300.jpg" alt="Figure 4: Login form for smart parking for cars"></p><p>3、将 <ruby>函数<rt>function</rt></ruby> 节点连接到 <ruby>模板<rt>template</rt></ruby> 节点，模板节点基于提供的模板创建一个 Web API。</p><p>4、将 <ruby>模板<rt>template</rt></ruby> 节点连接到 <ruby>http 响应<rt>http response</rt></ruby> 节点，它将响应 <ruby>http 输入<rt>http in</rt></ruby> 节点的请求。</p><p><img src="https://www.opensourceforu.com/wp-content/uploads/2022/04/Figure-5-Submission-Form-of-Metro-Smart-Car-Parking300.jpg" alt="Figure 5: Submission form for smart parking for cars"></p><h3 id="提交表单" tabindex="-1">提交表单 <a class="header-anchor" href="#提交表单" aria-label="Permalink to “提交表单”">​</a></h3><p>1、拖放 <ruby>http 输入<rt>http in</rt></ruby> 节点并将其连接到 json 节点，json 节点将数据转换为 JSON 字符串进行通信。</p><p>2、将 <ruby>http 输入<rt>http in</rt></ruby> 节点连接到 <ruby>调试<rt>debug</rt></ruby> 节点，调试节点的调试监控器会输出结果。</p><p>3、将 json 节点放置并连接到 <ruby>函数<rt>function</rt></ruby> 节点，将后者连接到 <ruby>http 响应<rt>http response</rt></ruby> 节点。</p><p>创建完整流程后，单击 Node-RED 窗口右上角的 <ruby>部署<rt>Deploy</rt></ruby> 按钮。访问 <code>http://127.0.0.1:1880/ui/</code> 这个链接查看用户界面。</p><p>输入链接然后单击 <ruby>提交<rt>Submit</rt></ruby> 后，该链接会跳转到下一页，你可以在该页面阅读所有新闻。</p><h3 id="node-red-工作流程" tabindex="-1">Node-RED 工作流程 <a class="header-anchor" href="#node-red-工作流程" aria-label="Permalink to “Node-RED 工作流程”">​</a></h3><p>在单个 Node-RED 流程中，你可以创建登录表单和提交表单，如图 4 和图 5 所示。</p><p>现在我们将配置节点属性。</p><h4 id="登录表单-1" tabindex="-1">登录表单 <a class="header-anchor" href="#登录表单-1" aria-label="Permalink to “登录表单”">​</a></h4><p>编辑 <ruby>http 输入<rt>http in</rt></ruby> 属性：</p><ul><li><ruby>方法<rt>method</rt></ruby> 选择 “Get”</li><li><ruby>网址<rt>URL</rt></ruby> 设为 <code>/MetroStation</code></li><li><ruby>名称<rt>name</rt></ruby> 配置为 “<ruby>智能停车系统<rt>Smart Parking</rt></ruby>”。</li></ul><p>（LCTT 译注：下文 http 响应节点的名称为 Smart parking，p 字母小写，为了区分，此处中文翻译成智能停车系统。）</p><p><img src="https://www.opensourceforu.com/wp-content/uploads/2022/04/Figure-6-Http-in-Node-Property-Configurations300.jpg" alt="Figure 6: Http in node property configurations"></p><blockquote><p>注意：URL 可以使用任何用户定义的本地变量。</p></blockquote><p>现在选择 <ruby>函数<rt>function</rt></ruby> 节点，编辑函数节点属性：输入代码 <code>msg.url = project</code> ，并配置代码 <ruby>名称<rt>name</rt></ruby> 字段为 “<ruby>项目提交<rt>Project Submission</rt></ruby>”。</p><p><img src="https://www.opensourceforu.com/wp-content/uploads/2022/04/Figure-7-Function-Node-Property-Configurations300.jpg" alt="Figure 7: Function node property configurations"></p><p>在 <ruby>模板<rt>template</rt></ruby> 节点的属性窗口，为登录表单配置相应的 HTML 代码，并将代码 <ruby>名称<rt>name</rt></ruby> 命名为 “<ruby>显示面板<rt>Display panel</rt></ruby>”。在此流程使用了 Mustache 模板格式（LCTT 译注：Mustache 是胡子的意思，因为它的嵌入标记 <code>{{ }}</code> 非常像胡子）。Mustache 是一个简单的 Web 模板系统，被描述为无逻辑的模板引擎。Mustache 没有任何显式的控制流语句，例如 <code>if</code> 和 <code>else</code> 条件和 <code>for</code> 循环。可以通过使用块标签处理列表和lambdas 来实现循环和条件评估。</p><p><img src="https://www.opensourceforu.com/wp-content/uploads/2022/04/Figure-8-Template-Node-Property-Configurations300.jpg" alt="Figure 8: Template node property configurations"></p><p>配置编辑 <ruby>http 响应<rt>http response</rt></ruby> 节点的属性，<ruby>名称<rt>name</rt></ruby> 设为 “<ruby>智能停车<rt>Smart parking</rt></ruby>”（图 9） 。</p><p><img src="https://www.opensourceforu.com/wp-content/uploads/2022/04/Figure-9-Template-Node-Property-Configurations300.jpg" alt="Figure 9: Http response node property configurations"></p><h4 id="提交表单-1" tabindex="-1">提交表单 <a class="header-anchor" href="#提交表单-1" aria-label="Permalink to “提交表单”">​</a></h4><p>在 <ruby>http 输入<rt>http in</rt></ruby> 节点的编辑属性窗口，<ruby>方法<rt>method</rt></ruby> 选择 “POST” ，<ruby>网址<rt>URL</rt></ruby> 设为 <code>/project</code>。</p><p><img src="https://www.opensourceforu.com/wp-content/uploads/2022/04/Figure-10-Http-in-Node-Property-Configurations300.jpg" alt="Figure 10: Http in node property configurations"></p><p>在 JSON 节点的编辑窗口，<ruby>操作<rt>Action</rt></ruby>设为 “<ruby>JSON字符串与对象互转<rt>Convert between JSON String &amp; Object</rt></ruby>”，参考图 11。</p><p><img src="https://www.opensourceforu.com/wp-content/uploads/2022/04/Figure-11-Json-Node-Property-Configurations300.jpg" alt="Figure 11: JSON node property configurations"></p><p><ruby>函数<rt>function</rt></ruby> 节点的配置如图 12 所示。</p><p><img src="https://www.opensourceforu.com/wp-content/uploads/2022/04/Figure-12-Function-Node-Property-Configurations300.jpg" alt="Figure 12: Function node property configurations"></p><p>在 <ruby>http 响应<rt>http response</rt></ruby> 节点，编辑属性 <ruby>名称<rt>name</rt></ruby> 为 “<ruby>已提交项目<rt>Project Submitted</rt></ruby>”。</p><p><img src="https://www.opensourceforu.com/wp-content/uploads/2022/04/Figure-13-Http-Response-Node-Property-Configurations300.jpg" alt="Figure 13: Http response node property configurations"></p><blockquote><p>注意：添加带有评论的评论节点作为 “登录表单” 和 “提交表单”。</p></blockquote><p><img src="https://www.opensourceforu.com/wp-content/uploads/2022/04/Figure-14-Debug-Node-Property-Configurations300.jpg" alt="Figure 14: Debug node property configurations"></p><h3 id="用户界面的控制面板" tabindex="-1">用户界面的控制面板 <a class="header-anchor" href="#用户界面的控制面板" aria-label="Permalink to “用户界面的控制面板”">​</a></h3><p>当用户单击 <ruby>提交<rt>Submit</rt></ruby>，给出的数据将显示在用户界面和调试节点。如果单击 <ruby>重置<rt>Reset</rt></ruby>，详细信息将被清除，允许用户输入新的详细信息（图15）。</p><p><img src="https://www.opensourceforu.com/wp-content/uploads/2022/04/Figure-15-User-Login-UI300.jpg" alt="Figure 15: User login UI"></p><p>地铁停车费率通过超链接提供，收费表在用户界面显示。因此，汽车智能停车系统通过适当的超链接实现自动化，展示地铁站的停车费。该自动化系统的最终输出可以在 Node-RED 控制面板的用户界面和调试监控器调取和展示。</p><p><img src="https://www.opensourceforu.com/wp-content/uploads/2022/04/Figure-16-Parking-Tariff-Metro300.jpg" alt="Figure 16: Metro parking tariff"></p><hr>',58)),a("p",null,[r[1]||(r[1]=t("via: ",-1)),e(o,{href:"https://www.opensourceforu.com/2022/06/build-a-smart-parking-system-for-a-metro-station/"},{default:p(()=>[...r[0]||(r[0]=[t("https://www.opensourceforu.com/2022/06/build-a-smart-parking-system-for-a-metro-station/",-1)])]),_:1})]),a("p",null,[r[6]||(r[6]=t("作者：",-1)),e(o,{href:"https://www.opensourceforu.com/author/dr-maheswari-r/"},{default:p(()=>[...r[2]||(r[2]=[t("Dr Maheswari R.",-1)])]),_:1}),r[7]||(r[7]=t(" 选题：",-1)),e(o,{href:"https://github.com/lkxed"},{default:p(()=>[...r[3]||(r[3]=[t("lkxed",-1)])]),_:1}),r[8]||(r[8]=t(" 译者：",-1)),e(o,{href:"https://github.com/Maisie-x"},{default:p(()=>[...r[4]||(r[4]=[t("Maisie-x",-1)])]),_:1}),r[9]||(r[9]=t(" 校对：",-1)),e(o,{href:"https://github.com/wxy"},{default:p(()=>[...r[5]||(r[5]=[t("wxy",-1)])]),_:1})]),a("p",null,[r[12]||(r[12]=t("本文由 ",-1)),e(o,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...r[10]||(r[10]=[t("LCTT",-1)])]),_:1}),r[13]||(r[13]=t(" 原创编译，",-1)),e(o,{href:"https://linux.cn/"},{default:p(()=>[...r[11]||(r[11]=[t("Linux中国",-1)])]),_:1}),r[14]||(r[14]=t(" 荣誉推出",-1))])])}const F=n(b,[["render",d]]);export{S as __pageData,F as default};
